/**
 *  売上CSVエクスポートレスポンス（フロントエンド返却用）
 *
 *  csv_bytes を base64 エンコードして返す。
 *  フロントエンド側で base64デコード → Blob → ダウンロード保存する。
 */
export type SalesExportResponse = {
	// UTF-8 BOM付きCSVバイト列のbase64エンコード
	bytes_base64: string,
	// 推奨ファイル名
	suggested_filename: string,
	// MIMEタイプ
	content_type: string,
	// 文字エンコーディング名
	encoding: string,
	// エクスポート件数
	record_count: number,
};

/**
 *  集計モード
 *
 *  response serialize 時に snake_case 出力（"by_product" / "by_department"）。
 *  request 引数は `get_monthly_sales(mode: String)` で受け取り CMD 層で変換する（H-1）。
 */
export type SalesMode = "by_product" | "by_department";

/**
 *  レポート種別（CSVエクスポート用）
 *
 *  `serde::Deserialize` + `specta::Type` + `#[serde(rename_all = "snake_case")]` で
 *  frontend bindings から `"daily" | "monthly_by_product" | "monthly_by_department"` literal union として
 *  受け取り、CMD 層で文字列 validation なく直接 enum として deserialize される（H-5 / Q-6 A 案）。
 */
export type SalesReportType =
// 日次（target: YYYY-MM-DD）
"daily" |
// 月次・商品別（target: YYYY-MM）
"monthly_by_product" |
// 月次・部門別（target: YYYY-MM）
"monthly_by_department";

